const MULT=new Proxy({}, {get:(_,ticker)=>{let b=DATA.benchmarkSnapshots.find(x=>x.ticker===ticker),q=window.MDLMarket?.get(ticker)?.price;if(!b||!q||!b.priceReturnDollars)return 1;let shares=b.shares||b.baselineInvestment/b.inceptionPrice,desired=(q-b.inceptionPrice)*shares;return desired/b.priceReturnDollars}});
const pages=[['dashboard','Dashboard','Front door to the experiment.'],['holdings','Covered Call Holdings','Current holdings, open calls, and opportunity.'],['calls','Covered Call Ledger','History summary, covered-call audit trail, and other ledger transactions.'],['sandbox','Sandbox','Interactive educational model using real trades from the experiment.'],['universe','Investment Universe','Editable Core Moat and Tactical universe.'],['schd','SCHD Universe','SCHD holdings as a filtered master-data view.'],['benchmarks','Benchmark Comparison','Strategy versus realistic alternatives.'],['methodology','Technical Reference & Methodology','Definitions, assumptions, operating process, and glossary.'],['marketdb','Internal · Market Database','S&P 500 master data and refresh controls.']];
const market=new Set(['dashboard','holdings','benchmarks','universe','schd','marketdb']);
const fmt=v=>v==null?'—':Number(v).toLocaleString(undefined,{style:'currency',currency:'USD',maximumFractionDigits:0}),pct=v=>v==null?'—':(Number(v).toFixed(2)+'%'),cls=v=>(v||0)>=0?'good':'bad';
function tip(t,b){return `<span class="info" tabindex="0">ⓘ<span class="tip"><b>${t}</b><br>${b}</span></span>`}
function quote(t,p){let q=window.MDLMarket?.get(t)?.price;return mode==='live'&&q?q:p}
function holdingRows(){return DATA.holdings.map(h=>{let price=quote(h.ticker,h.price),value=price*h.shares,gl=value-h.cost;return{...h,price,value,stock_gl:gl}})}
function combined(){if(mode==='baseline')return DATA.combined;let hs=holdingRows(),stock_val=hs.reduce((s,h)=>s+h.value,0),stock_gl=hs.reduce((s,h)=>s+h.stock_gl,0),total=stock_val+DATA.combined.cash,ret=stock_gl+DATA.combined.premiums+DATA.combined.dividends+DATA.combined.interest+DATA.combined.realized_sale_gains-DATA.combined.fees;return{...DATA.combined,stock_val,stock_gl,total,strategy_total_return:ret,strategy_return_pct:ret/DATA.combined.return_baseline*100}}
function expDate(t){let m=(t||'').match(/([A-Z][A-Z]{2})\s+(\d{1,2}),\s+(\d{4})/);return m?new Date(`${m[1]} ${m[2]}, ${m[3]} UTC`):null}
function days(exp){let e=expDate(exp);if(!e)return null;let d=mode==='live'?new Date():new Date(DATA.asOf+'T00:00:00Z');return Math.ceil((e-d)/86400000)}
async function refreshLive(){if(!window.MDLMarket)return;mode='live';await MDLMarket.refreshPortfolio();let s=MDLMarket.status();quoteStatus=s.portfolioStatus;lastQuoteRefresh=s.lastPortfolioRefresh?new Date(s.lastPortfolioRefresh):null;render()}
function nav(){document.getElementById('nav').innerHTML=pages.map(p=>`<button class="${page===p[0]?'active':''} ${p[0]==='marketdb'?'internalNav':''}" onclick="page='${p[0]}';render()">${p[1]}</button>`).join('')}
function modeUI(){let el=document.getElementById('modeToggle');if(!market.has(page)){el.innerHTML='';return}let s=MDLMarket.status(),stamp=s.lastPortfolioRefresh?new Date(s.lastPortfolioRefresh).toLocaleString():'Not yet refreshed',buttons=`<button class="${mode==='live'?'active':''}" onclick="mode='live';render()">Live</button><button class="${mode==='baseline'?'active':''}" onclick="mode='baseline';render()">Baseline</button>`;if(['universe','schd','marketdb'].includes(page)){el.innerHTML=buttons;return}if(page==='benchmarks'){let bt=MDLMarket.benchmarkTickers(),priced=bt.filter(t=>MDLMarket.get(t)?.price).length;el.innerHTML=`<span class="quoteStatus stableStatus">Benchmark ETFs ${priced}/${bt.length} priced</span>${buttons}`;return}let total=MDLMarket.holdingsTickers().length,current=s.portfolioRefreshing?s.portfolioDone:(s.portfolioFailed?total-s.portfolioFailed:s.lastPortfolioRefresh?total:0),manual=s.portfolioRefreshing?`Holdings ${current}/${total} refreshing`:`Holdings ${current}/${total} current · ${stamp}`;if(page==='dashboard'){let bt=MDLMarket.benchmarkTickers(),priced=bt.filter(t=>MDLMarket.get(t)?.price).length;manual+=` · Benchmark ETFs ${priced}/${bt.length}`}el.innerHTML=`<span class="quoteStatus stableStatus">${safeText(manual)}</span><button class="refreshLive" onclick="refreshLive()" ${s.portfolioRefreshing?'disabled':''}>Refresh Portfolio</button>${buttons}`}
function banner(){return market.has(page)?`<div class="liveHint"><b>${mode==='live'?'Shared market database':'Ledger snapshot'}:</b> ${mode==='live'?'Every displayed price is read from the same persisted market store. No downstream page calls Finnhub directly.':'Fidelity transaction snapshot through '+(DATA.ledgerThrough||DATA.asOf)+'; verified market prices '+DATA.asOf+'.'}</div>`:''}
function metric(l,v,k=''){return`<section class="card"><div class="label">${l}</div><div class="value ${k}">${v}</div></section>`}function bucket(b){return`<span class="pill">${b}</span>`}
function optionMap(){let m={};DATA.options.forEach(o=>m[o.ticker]=o);return m}
function callSalesByTicker(){let m={};DATA.transactions.filter(t=>t.category==='Sell Call').forEach(t=>{if(t.ticker)(m[t.ticker] ||= []).push(t)});Object.values(m).forEach(a=>a.sort((x,y)=>new Date(x.date)-new Date(y.date)));return m}
function trendFor(ticker,currentPremium){let sales=callSalesByTicker()[ticker]||[];if(sales.length<2)return{trend:'Not enough history',icon:'⚪',note:'Only one covered-call sale in ledger'};let prev=sales[sales.length-2].amount||0,curr=currentPremium||sales[sales.length-1].amount||0,delta=curr-prev,dp=prev?delta/prev*100:0;if(dp>10)return{trend:'Premium Increasing',icon:'🟢',note:`Up ${fmt2(delta)} vs prior sale (${pct(dp)})`};if(dp<-10)return{trend:'Premium Decreasing',icon:'🔴',note:`Down ${fmt2(Math.abs(delta))} vs prior sale (${pct(dp)})`};return{trend:'Premium Flat',icon:'🟡',note:`Within ±10% of prior sale (${pct(dp)})`}}
function fmt2(v){return(v||0).toLocaleString(undefined,{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2})}
function enrichedHoldings(){let opts=optionMap();return holdingRows().map(h=>{let active=opts[h.ticker],strike=active?.strike?parseFloat(active.strike):null,dist=h.price&&strike?((strike-h.price)/h.price*100):null,d=days(active?.expiration),premiums=h.premiums||0,dividends=h.dividends||0,totalContribution=(h.stock_gl||0)+premiums+dividends,premiumYield=h.cost?premiums/h.cost*100:0,trend=trendFor(h.ticker,active?.cost||0),risk=dist==null?'—':dist<0?'In the money':dist<2?'Close to strike':dist<6?'Manage':'Comfortable';return{...h,active,strike,dist,days:d,premiums,dividends,totalContribution,premiumYield,trend,risk}})}
function currentPositionRows(){return enrichedHoldings().sort((a,b)=>{let ar=a.bucket==='Review'?1:0,br=b.bucket==='Review'?1:0;if(ar!==br)return ar-br;return(a.days??999)-(b.days??999)})}
function contributionRows(){return enrichedHoldings().sort((a,b)=>{let ar=a.bucket==='Review'?1:0,br=b.bucket==='Review'?1:0;if(ar!==br)return ar-br;return b.totalContribution-a.totalContribution})}
function accountShort(a){return(a||'').replace(' Rollover','')}
function sandboxCaseLabel(c){return c?.label || `${c?.ticker||'Case'} — ${c?.name||'Case Study'}`}
function sandboxCaseName(c){if(c?.name)return c.name;let h=(DATA.holdings||[]).find(x=>x.ticker===c?.ticker),u=(DATA.universe||[]).find(x=>x.ticker===c?.ticker);return h?.name||u?.name||'Case Study'}
function dashboard(){let c=combined(),pulse=benchRows().filter(b=>['SPY','QQQ','DIA'].includes(b.ticker)),alloc=holdingRows().reduce((m,h)=>{m[h.sector]=(m[h.sector]||0)+h.value;return m},{}),allocTotal=Object.values(alloc).reduce((s,v)=>s+v,0)||1;return`${banner()}<div class="stack"><section class="hero"><div class="label">Strategy Overview</div><div style="font-size:20px;font-weight:800;margin-top:8px;line-height:1.35">A strategic sector-balanced portfolio of dividend-paying companies, enhanced through covered calls, with performance compared to income vehicles, traditional benchmarks, safe assets, and inflation.</div><div class="small" style="margin-top:12px">Data. Models. Assumptions. You decide.</div></section><div class="grid two"><section class="hero"><div class="label">${mode==='live'?'Live Strategy Value':'Since Inception Performance'}</div><div class="value ${cls(c.strategy_total_return)}">${fmt(c.strategy_total_return)} <span style="font-size:28px">(${pct(c.strategy_return_pct)})</span></div><div class="small">Primary objective: cash flow, followed by capital preservation, followed by growth above inflation.</div></section><section class="card"><div class="label">Market Pulse ${tip('Market Pulse','Uses the same benchmark total-return method as Benchmark Comparison.')}</div>${pulse.map(m=>`<div style="display:flex;justify-content:space-between;margin:10px 0"><span>${m.name} <span class="small">(${m.ticker})</span></span><b class="${cls(m.totalReturnPct)}">${pct(m.totalReturnPct)}</b></div>`).join('')}</section></div><div class="grid cards">${metric('Portfolio Value',fmt(c.total))}${metric('Cash',fmt(c.cash))}${metric('Premium Income',fmt(c.premiums),'good')}${metric('Dividends + Interest',fmt(c.dividends+c.interest),'good')}</div><section class="card"><div class="label">Show Your Work</div><table><tbody><tr><td>Net capital appreciation ${tip('Net capital appreciation','Realized plus unrealized stock gains/losses since inception.')}</td><td class="num ${cls(c.stock_gl)}">${fmt(c.stock_gl)}</td></tr><tr><td>Option premium income</td><td class="num good">${fmt(c.premiums)}</td></tr><tr><td>Dividend income</td><td class="num good">${fmt(c.dividends)}</td></tr><tr><td>Interest income</td><td class="num good">${fmt(c.interest)}</td></tr><tr><td>Realized sale gains</td><td class="num ${cls(c.realized_sale_gains)}">${fmt(c.realized_sale_gains)}</td></tr><tr><td>Fees</td><td class="num bad">-${fmt(c.fees)}</td></tr><tr><td><b>Strategy Total Return</b></td><td class="num ${cls(c.strategy_total_return)}"><b>${fmt(c.strategy_total_return)}</b></td></tr></tbody></table></section><section class="card"><div class="label">Current Portfolio Sector Allocation</div><table><tbody>${Object.entries(alloc).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<tr><td>${k}</td><td class="num">${pct(v/allocTotal*100)}</td></tr>`).join('')}</tbody></table></section></div>`}
function holdingsPage(){let pos=currentPositionRows(),c=combined(),stockValue=pos.reduce((s,h)=>s+h.value,0),stockGL=pos.reduce((s,h)=>s+h.stock_gl,0),openCalls=pos.filter(h=>h.active).length,near=pos.filter(h=>h.dist!=null&&h.dist<2).length,optVal=DATA.combined.opt_val||0;let tabs=`<div class="subtabs"><button class="${holdingsSub==='position'?'active':''}" onclick="holdingsSub='position';render()">1. Current Position</button><button class="${holdingsSub==='opportunity'?'active':''}" onclick="holdingsSub='opportunity';render()">2. Opportunity</button></div>`;let cards=`<div class="grid cards">${metric('Portfolio Value',fmt(c.total))}${metric('Stock Holdings Value',fmt(stockValue))}${metric('Cash',fmt(c.cash))}${metric('Near / In The Money',near,near?'warn':'')}</div>`;let reconcile=`<section class="note"><b>Portfolio Value vs Stock Holdings Value:</b> Portfolio Value includes stock holdings, cash, and open option liability. Current snapshot: ${fmt(stockValue)} stock + ${fmt(c.cash)} cash + ${fmt(optVal)} open option value = ${fmt(c.total)} portfolio value. Stock Holdings Value answers “what are the shares worth?” Portfolio Value answers “what is the account worth if viewed as a whole today?”</section>`;let position=`<section class="card"><div class="label">Current Position View</div><p class="small">Snapshot view: what we own today, which covered call is attached, and how close each position is to assignment. <b>Near / In The Money</b> counts positions whose call strike is less than 2% above the current stock price or already below it.</p><table><thead><tr><th>Holding</th><th>Account</th><th>Bucket</th><th class="num">Shares</th><th class="num">Price</th><th class="num">Stock Value</th><th class="num">Stock G/L</th><th>Open Call</th><th class="num">Days</th><th class="num">Strike</th><th class="num">Distance to Strike</th><th class="num">Call P/L if Closed</th><th>Status</th></tr></thead><tbody>${pos.map(h=>`<tr><td class="ticker">${h.ticker}<div class="small">${h.name}</div></td><td>${accountShort(h.account)}</td><td>${bucket(h.bucket)}</td><td class="num">${h.shares}</td><td class="num">${fmt2(h.price)}</td><td class="num">${fmt(h.value)}</td><td class="num ${cls(h.stock_gl)}">${fmt(h.stock_gl)}</td><td>${h.active?h.active.description:'—'}</td><td class="num">${h.days??'—'}</td><td class="num">${h.active?.strike?'$'+h.active.strike:'—'}</td><td class="num ${cls(h.dist)}">${h.dist==null?'—':pct(h.dist)}</td><td class="num ${cls(h.active?.gl)}">${h.active?fmt(h.active.gl):'—'}</td><td>${h.risk}</td></tr>`).join('')}</tbody></table><p class="small"><b>Column notes:</b> Stock G/L is the gain/loss on the shares only. Call P/L if Closed is the option leg only: the current gain/loss if the open call were bought back today. They are intentionally different numbers.</p></section>`;let opportunity=`<section class="card"><div class="label">Covered Call Opportunity / Watch List</div><p class="small">Forward-looking management view for current holdings. Rule-based comments update when new ledger/open-call data is imported.</p><table><thead><tr><th>Holding</th><th>Trend</th><th class="num">Current Premium</th><th class="num">Premium / Cost</th><th>Expiration</th><th class="num">Strike</th><th class="num">Distance</th><th>Auto Comment</th></tr></thead><tbody>${pos.map(h=>`<tr><td class="ticker">${h.ticker}<div class="small">${h.name}</div></td><td>${h.trend.icon} ${h.trend.trend}</td><td class="num good">${h.active?fmt(h.active.cost):'—'}</td><td class="num">${h.active&&h.cost?pct(h.active.cost/h.cost*100):'—'}</td><td>${h.active?.expiration||'—'}</td><td class="num">${h.active?.strike?'$'+h.active.strike:'—'}</td><td class="num ${cls(h.dist)}">${h.dist==null?'—':pct(h.dist)}</td><td>${h.trend.note}</td></tr>`).join('')}</tbody></table></section>`;let active=holdingsSub==='opportunity'?opportunity:position;return`${banner()}<div class="stack"><div class="note"><b>Covered Call Holdings:</b> current operational portfolio page. Current Position is today’s snapshot; Opportunity is the forward-looking management view. Cumulative contribution/history has moved to Covered Call Ledger.</div>${tabs}${cards}${reconcile}${active}</div>`}
function historyPremiumYield(h){let basis=(h.cost||h.purchaseCost||0);if(!basis){let current=(DATA.holdings||[]).find(x=>x.ticker===h.ticker);basis=current?.cost||0}return basis?((h.premiums||0)/basis*100):null}
function callsPage(){let cc=DATA.transactions.filter(t=>['Sell Call','Expired Call','Assigned Option'].includes(t.category));let other=DATA.transactions.filter(t=>!['Sell Call','Expired Call','Assigned Option'].includes(t.category));let totalPremium=cc.filter(t=>t.category==='Sell Call').reduce((s,t)=>s+(t.amount||0),0),expired=cc.filter(t=>t.category==='Expired Call').length,assigned=cc.filter(t=>t.category==='Assigned Option').length;let hist=[...DATA.history].sort((a,b)=>(b.totalContribution||0)-(a.totalContribution||0));return`<div class="stack"><div class="grid three">${metric('Covered Call Premiums',fmt(totalPremium),'good')}${metric('Expired Calls',expired)}${metric('Assignments',assigned,'warn')}</div><section class="card"><div class="label">History Summary</div><p class="small">Strategy history and completed-position summary, sorted by total contribution. This preserves the former Strategy History page and adds Premium Yield.</p><table><thead><tr><th>Ticker</th><th>Sector</th><th>Bucket</th><th class="num">Stock G/L</th><th class="num">Premiums</th><th class="num">Dividends</th><th class="num">Premium Yield</th><th class="num">Fees</th><th class="num">Total Contribution</th></tr></thead><tbody>${hist.map((h,i)=>{let py=historyPremiumYield(h);return`<tr><td class="ticker">${i===0?'🏆 ':''}${h.ticker}</td><td>${h.sector}</td><td>${bucket(h.bucket)}</td><td class="num ${cls(h.stockGL)}">${fmt(h.stockGL)}</td><td class="num good">${fmt(h.premiums)}</td><td class="num good">${fmt(h.dividends)}</td><td class="num good">${py==null?'—':pct(py)}</td><td class="num bad">${fmt(h.fees)}</td><td class="num ${cls(h.totalContribution)}"><b>${fmt(h.totalContribution)}</b></td></tr>`}).join('')}</tbody></table></section><section class="card"><div class="label">Covered Call Ledger</div><p class="small">Covered-call audit trail parsed from the source-of-truth ledger.</p><table><thead><tr><th>Date</th><th>Account</th><th>Event</th><th>Ticker</th><th>Description</th><th class="num">Amount / Premium</th><th class="num">Cash Balance</th></tr></thead><tbody>${cc.map(t=>`<tr><td>${t.date}</td><td>${accountShort(t.account)}</td><td>${t.category}</td><td class="ticker">${t.ticker}</td><td>${t.action}</td><td class="num ${cls(t.amount)}">${fmt(t.amount)}</td><td class="num">${fmt(t.cash)}</td></tr>`).join('')}</tbody></table></section><section class="card"><div class="label">Other Account Transactions</div><p class="small">Everything else from the same source-of-truth ledger: stock buys/sales, dividends, interest, deposits, rollovers, and other account activity.</p><table><thead><tr><th>Date</th><th>Account</th><th>Category</th><th>Ticker</th><th>Description</th><th class="num">Amount</th><th class="num">Cash</th></tr></thead><tbody>${other.map(t=>`<tr><td>${t.date}</td><td>${accountShort(t.account)}</td><td>${t.category}</td><td class="ticker">${t.ticker}</td><td>${t.action}</td><td class="num ${cls(t.amount)}">${fmt(t.amount)}</td><td class="num">${fmt(t.cash)}</td></tr>`).join('')}</tbody></table></section></div>`}
function dateShort(s){if(!s)return'Current';let d=new Date(s+'T00:00:00Z');return d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'})}
function historyRows271(){return[...(DATA.historyEpisodes||DATA.history)].sort((a,b)=>(a.current===b.current?0:a.current?-1:1)||((b.totalContribution||0)-(a.totalContribution||0)))}
function historySummary271(){let rows=historyRows271();return`<section class="card"><div class="label">History Summary</div><p class="small">Current holdings are grouped first and ranked by total contribution; completed positions follow. Holding dates and exit disposition preserve why each position left the portfolio.</p><table><thead><tr><th>Ticker</th><th>Held</th><th>Exit / Status</th><th>Bucket</th><th class="num">Stock G/L</th><th class="num">Premiums</th><th class="num">Dividends</th><th class="num">Premium Yield</th><th class="num">Total Contribution</th></tr></thead><tbody>${rows.map(h=>{let py=historyPremiumYield(h),held=`${dateShort(h.heldFrom||h.firstDate)} – ${h.current?'Current':dateShort(h.heldTo||h.lastDate)}`;return`<tr class="${h.current?'currentHistory':''}"><td class="ticker">${safeText(h.displayTicker||h.ticker)}</td><td>${held}</td><td>${safeText(h.exitDisposition||'Current')}</td><td>${bucket(h.bucket)}</td><td class="num ${cls(h.stockGL)}">${fmt(h.stockGL)}</td><td class="num good">${fmt(h.premiums)}</td><td class="num good">${fmt(h.dividends)}</td><td class="num good">${py==null?'—':pct(py)}</td><td class="num ${cls(h.totalContribution)}"><b>${fmt(h.totalContribution)}</b></td></tr>`}).join('')}</tbody></table></section>`}
function ledgerTable271(rows){return`<section class="card"><div class="label">Transaction Ledger</div><table><thead><tr><th>Date</th><th>Account</th><th>Category</th><th>Ticker</th><th>Description</th><th class="num">Amount</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${t.date}</td><td>${accountShort(t.account)}</td><td>${t.category}</td><td class="ticker">${t.ticker||'—'}</td><td>${safeText(t.action)}</td><td class="num ${cls(t.amount)}">${fmt(t.amount)}</td></tr>`).join('')}</tbody></table></section>`}
function monthlyScore271(m){let newPos=m.newPositions.length?m.newPositions.join(', '):'None';return`<div class="grid cards">${metric('Realized Contribution',fmt(m.realizedContribution),cls(m.realizedContribution))}${metric('Contribution / Baseline',pct(m.realizedContributionPct),cls(m.realizedContributionPct))}${metric('SPY Price Return',pct(m.spyReturnPct),cls(m.spyReturnPct))}${metric('Premium Income',fmt(m.premium),'good')}</div><section class="card"><div class="label">${m.label} Scorecard</div><table><tbody><tr><td>Dividends + interest</td><td class="num good">${fmt(m.dividends+m.interest)}</td></tr><tr><td>Realized stock G/L</td><td class="num ${cls(m.realizedStockGL)}">${fmt(m.realizedStockGL)}</td></tr><tr><td>SPY comparison (month-end close to month-end close)</td><td class="num ${cls(m.spyReturnPct)}">${fmt2(m.spyStart)} → ${fmt2(m.spyEnd)} · ${pct(m.spyReturnPct)}</td></tr><tr><td>Assignments / called-away positions</td><td class="num">${m.assignments}</td></tr><tr><td>Intentional exits</td><td class="num">${m.intentionalExits}</td></tr><tr><td>New positions</td><td class="num">${safeText(newPos)}</td></tr><tr><td>Capital deployed into stock purchases</td><td class="num">${fmt(m.capitalDeployed)}</td></tr></tbody></table><p class="small"><b>Performance convention:</b> monthly realized contribution = premiums + dividends + interest + realized stock G/L, divided by the fixed experiment baseline for the percentage. It is not labeled as total portfolio return because the ledger alone cannot reconstruct every historical month-end option mark. SPY is shown separately as a price-return benchmark, not an apples-to-apples total-return claim.</p></section><section class="note commentary"><b>${m.label} 2026:</b> ${safeText(m.narrative)}</section>${ledgerTable271(m.transactions)}`}
function sinceInception271(){let months=DATA.monthlyLedger||[];return`${historySummary271()}<section class="card"><div class="label">Month-to-Month Performance</div><table><thead><tr><th>Month</th><th class="num">Realized Contribution</th><th class="num">% of Baseline</th><th class="num">SPY Price Return</th><th class="num">Premiums</th><th class="num">Dividends + Interest</th><th class="num">Assignments</th><th class="num">Capital Deployed</th></tr></thead><tbody>${months.map(m=>`<tr><td><b>${m.label}</b></td><td class="num ${cls(m.realizedContribution)}">${fmt(m.realizedContribution)}</td><td class="num ${cls(m.realizedContributionPct)}">${pct(m.realizedContributionPct)}</td><td class="num ${cls(m.spyReturnPct)}">${pct(m.spyReturnPct)}</td><td class="num good">${fmt(m.premium)}</td><td class="num good">${fmt(m.dividends+m.interest)}</td><td class="num">${m.assignments}</td><td class="num">${fmt(m.capitalDeployed)}</td></tr>`).join('')}</tbody></table></section>${ledgerTable271(DATA.transactions)}`}
function callsPageV271(){let months=DATA.monthlyLedger||[],tabs=`<div class="subtabs"><button class="${callsMonth==='all'?'active':''}" onclick="callsMonth='all';render()">Since Inception</button>${months.map(m=>`<button class="${callsMonth===m.key?'active':''}" onclick="callsMonth='${m.key}';render()">${m.label}</button>`).join('')}</div>`;let selected=months.find(m=>m.key===callsMonth);return`<div class="stack"><section class="hero"><div class="label">Covered Call Ledger · 2.7.1</div><div style="font-size:20px;font-weight:800;margin-top:8px">History with holding dates, exit reasons, and month-by-month operating results.</div></section>${tabs}${selected?monthlyScore271(selected):sinceInception271()}</div>`}
function historyPage(){return historySummary271()}
function universePage(){return`<div class="stack"><section class="card"><div class="label">Portfolio Lifecycle</div><p><b>Core</b> holdings form the long-term foundation. <b>Bullpen</b> names are qualified candidates. <b>Tactical</b> positions are opportunistic. <b>Review</b> means current holdings deserve attention. <b>Archived</b> means sold or removed but preserved for learning. <b>Benchmarks</b> are comparison vehicles, not recommendations.</p></section><section class="card"><div class="label">Investment Universe</div><table><thead><tr><th>Ticker</th><th>Name</th><th>Sector</th><th>Bucket</th><th>Notes</th></tr></thead><tbody>${DATA.universe.map(u=>`<tr><td class="ticker">${u.ticker}</td><td>${u.name}</td><td>${u.sector}</td><td>${bucket(u.bucket)}</td><td>${u.notes||u.reason||'—'}</td></tr>`).join('')}</tbody></table></section></div>`}
function benchRows(){let c=combined(),base=DATA.combined.return_baseline;let strategy={ticker:'STRATEGY',name:'Our Strategy',proxy:'Active portfolio',category:'Cash Flow',purpose:'Maximize sustainable cash flow',baselineInvestment:base,priceReturnDollars:c.stock_gl,incomeGenerated:DATA.combined.premiums+DATA.combined.dividends+DATA.combined.interest,totalReturnDollars:c.strategy_total_return,totalReturnPct:c.strategy_return_pct,endingValue:c.total};const liveSecurity=b=>{let x={...b},p=mode==='live'?MDLMarket.get(x.ticker)?.price:null;if(p&&x.inceptionPrice){let shares=x.baselineInvestment/x.inceptionPrice;x.currentPrice=p;x.price=p;x.shares=shares;x.priceReturnDollars=(p-x.inceptionPrice)*shares;x.totalReturnDollars=x.priceReturnDollars+(x.incomeGenerated||0);x.totalReturnPct=x.totalReturnDollars/x.baselineInvestment*100;x.endingValue=x.baselineInvestment+x.totalReturnDollars}return x};let rows=[strategy,...DATA.benchmarkSnapshots.map(liveSecurity)];let bnd=liveSecurity({ticker:'BND',name:'Total Bond Market',proxy:'BND',category:'Capital Preservation',purpose:'Broad bond market',baselineInvestment:base,inceptionPrice:73.64,currentPrice:73.64,priceReturnDollars:0,incomeGenerated:230,totalReturnDollars:230,totalReturnPct:230/base*100,endingValue:base+230});let hysa={ticker:'HYSA',name:'High-Yield Savings',proxy:'Cash',category:'Capital Preservation',purpose:'Cash preservation',baselineInvestment:base,priceReturnDollars:0,incomeGenerated:797,totalReturnDollars:797,totalReturnPct:797/base*100,endingValue:base+797};let tb={ticker:'TBILL3M',name:'3-Month T-Bills',proxy:'Treasury bills',category:'Capital Preservation',purpose:'Short-term Treasury income',baselineInvestment:base,priceReturnDollars:0,incomeGenerated:891,totalReturnDollars:891,totalReturnPct:891/base*100,endingValue:base+891};let spy=rows.find(r=>r.ticker==='SPY'),sfPrice=.6*(spy?.priceReturnDollars||0)+.4*(bnd.priceReturnDollars||0),sfIncome=.6*(spy?.incomeGenerated||0)+.4*(bnd.incomeGenerated||0),sfTotal=sfPrice+sfIncome;let sf={ticker:'60/40',name:'60/40 Portfolio',proxy:'60% SPY / 40% BND',category:'Traditional Retirement',purpose:'Traditional retirement allocation',baselineInvestment:base,priceReturnDollars:sfPrice,incomeGenerated:sfIncome,totalReturnDollars:sfTotal,totalReturnPct:sfTotal/base*100,endingValue:base+sfTotal};let cpi={ticker:'CPI',name:'Inflation / CPI',proxy:'CPI',category:'Purchasing Power',purpose:'Purchasing power hurdle',baselineInvestment:base,priceReturnDollars:562,incomeGenerated:0,totalReturnDollars:562,totalReturnPct:562/base*100,endingValue:base+562};rows.push(bnd,hysa,tb,sf,cpi);return rows.map(r=>['SPYI','SCHD'].includes(r.ticker)?{...r,category:'Cash Flow'}:['SPY','QQQ','DIA'].includes(r.ticker)?{...r,category:'Growth'}:r)}function benchmarksPage(){let cats=['Cash Flow','Growth','Capital Preservation','Traditional Retirement','Purchasing Power'],rows=benchRows();return`${banner()}<div class="stack"><section class="hero"><div class="label">Retirement Benchmark Framework</div><div style="font-size:18px;font-weight:800;margin-top:8px">Cash flow first. Capital preservation second. Growth above inflation third.</div></section>${cats.map(cat=>`<section class="card"><div class="label">${cat}</div><table><thead><tr><th>Portfolio</th><th>Purpose</th><th class="num">Capital Appreciation</th><th class="num">Income Generated</th><th class="num">Total Return</th><th class="num">Return %</th><th class="num">Ending Value</th></tr></thead><tbody>${rows.filter(r=>r.category===cat).map(r=>`<tr><td class="ticker">${r.name}<div class="small">${r.proxy||r.ticker}</div></td><td>${r.purpose}</td><td class="num ${cls(r.priceReturnDollars)}">${fmt(r.priceReturnDollars)}</td><td class="num good">${fmt(r.incomeGenerated)}</td><td class="num ${cls(r.totalReturnDollars)}"><b>${fmt(r.totalReturnDollars)}</b></td><td class="num ${cls(r.totalReturnPct)}">${pct(r.totalReturnPct)}</td><td class="num">${fmt(r.endingValue)}</td></tr>`).join('')}</tbody></table></section>`).join('')}</div>`}
function ledgerPage(){return`<section class="card"><div class="label">Ledger</div><p class="small">No Live/Baseline toggle. The ledger is the source-of-truth event log. Full imported dataset restored.</p><table><thead><tr><th>Date</th><th>Account</th><th>Category</th><th>Ticker</th><th>Description</th><th class="num">Amount</th><th class="num">Cash</th></tr></thead><tbody>${DATA.transactions.map(t=>`<tr><td>${t.date}</td><td>${t.account.replace(' Rollover','')}</td><td>${t.category}</td><td class="ticker">${t.ticker}</td><td>${t.action}</td><td class="num ${cls(t.amount)}">${fmt(t.amount)}</td><td class="num">${fmt(t.cash)}</td></tr>`).join('')}</tbody></table></section>`}
function importPage(){return`<div class="stack"><section class="hero"><div class="label">Monthly Refresh</div><div style="font-size:20px;font-weight:800;margin-top:8px">Baseline + new ledger activity + month-end positions = next official snapshot.</div></section><section class="card"><div class="label">Workflow</div><ol><li>Upload monthly Fidelity activity reports.</li><li>Reconcile buys, sells, dividends, premiums, fees, expirations, and assignments.</li><li>Update current holdings and open covered calls.</li><li>Update benchmark values using the same inception date and starting capital.</li><li>Freeze the new baseline.</li></ol></section></div>`}
function methodology(){let starting=DATA.combined.return_baseline;return`<div class="stack"><section class="hero"><div class="label">Technical Reference & Methodology</div><div style="font-size:20px;font-weight:800;margin-top:8px;line-height:1.35">The owner's manual for the experiment: definitions, assumptions, constraints, data sources, and update process.</div><div class="small" style="margin-top:12px">Every number should be self-explanatory or have one authoritative definition.</div></section><section class="card"><div class="label">Purpose</div><p>The purpose of this experiment is to evaluate whether a strategically selected portfolio of dividend-paying companies, enhanced through covered-call writing, can produce superior long-term cash generation while remaining competitive with passive investment alternatives.</p></section><section class="card"><div class="label">Investment Philosophy</div><ul><li>Prefer large-cap, blue-chip, dividend-paying companies.</li><li>Use covered calls to enhance cash flow while attempting to preserve capital.</li><li>Compare against realistic alternatives instead of judging the strategy in isolation.</li><li>Show the data, assumptions, and math so the reader can decide.</li></ul></section><section class="card"><div class="label">Initial Capital and Timeline</div><p>The benchmark baseline uses the exact starting capital in the experiment: <b>${fmt2(starting)}</b>. The experiment began with Portfolio A's account first. Portfolio B's account was added approximately one option cycle later after the initial operating process was established. That phased rollout matters because not all capital was deployed for the full comparison period.</p></section><section class="card"><div class="label">Real-World Constraints</div><p>This is a real brokerage experiment, not a perfect backtest. Results include cash settlement delays, two separate Fidelity accounts, limited 100-share lot sizing, available strike/expiration chains, imperfect timing, assignment risk, and occasional inefficient option chaining caused by cash availability and market conditions.</p></section><section class="card"><div class="label">Key Definitions</div><table><thead><tr><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td><b>Portfolio Value</b></td><td>Ledger cash plus current ledger shares multiplied by the latest available stock price. Open option value, premiums, dividends, cost basis, and realized gains are excluded.</td></tr><tr><td><b>Stock Holdings Value</b></td><td>Current market value of shares only. This excludes cash and open option liabilities.</td></tr><tr><td><b>Stock G/L</b></td><td>Gain or loss on the shares only: current stock value minus cost basis.</td></tr><tr><td><b>Call P/L if Closed</b></td><td>Gain or loss on the open option leg only if the call were bought back today.</td></tr><tr><td><b>Near / In The Money</b></td><td>A management flag for positions whose covered-call strike is less than 2% above the current stock price or already below it.</td></tr><tr><td><b>Distance to Strike</b></td><td>How far the covered-call strike is from the current stock price, expressed as a percentage.</td></tr><tr><td><b>Total Contribution</b></td><td>Stock G/L plus premiums plus dividends, less fees where applicable.</td></tr><tr><td><b>Premium Yield</b></td><td>Covered-call premium collected divided by the relevant cost basis.</td></tr><tr><td><b>Ledger</b></td><td>The source-of-truth transaction record used to build the tracker views.</td></tr></tbody></table></section><section class="card"><div class="label">Monthly Refresh Procedure</div><ol><li>Export or collect Fidelity activity and position data.</li><li>Reconcile buys, sells, dividends, premiums, fees, expirations, assignments, and cash movements.</li><li>Update current holdings and open covered calls.</li><li>Update benchmark values using the same baseline capital.</li><li>Run local smoke tests and review key pages.</li><li>Archive the release candidate.</li><li>Commit, push, and verify GitHub Pages only after acceptance review.</li></ol></section><section class="card"><div class="label">FAQ</div><p><b>Why does Portfolio Value differ from Stock Holdings Value?</b><br>Portfolio Value includes current stock holdings plus ledger cash. Open option value and cumulative income or gains are excluded. Stock Holdings Value only counts the shares.</p><p><b>Why are some dividends not shown on current holdings?</b><br>Current holdings only show income tied to positions still owned. Dashboard-level income includes prior holdings and interest.</p><p><b>What does Strike vs Current mean in the Sandbox?</b><br>It is the percentage distance between the covered-call strike and the current stock price. Positive means the strike is above the stock price; negative means the call is in the money.</p></section><section class="card"><div class="label">Experimental Rules</div><ul><li>Use real trades only; the ledger remains the source of truth.</li><li>No margin and no leverage.</li><li>Measure against realistic alternatives using the same baseline capital.</li><li>Document assumptions clearly so the reader can evaluate the result.</li></ul></section><section class="card"><div class="label">Known Limitations</div><p>Early results include capital ramp-up, cash drag, assigned positions, different account start dates, and changing opportunity sets. These constraints may make the comparison conservative in some periods and imperfect in others, but they reflect how the strategy is actually being executed.</p></section><section class="card"><div class="label">Live vs Baseline</div><p>Baseline is the official frozen experiment record. Live mode is a quote-driven overlay plus ledger entries after the baseline. The ledger remains the source of truth.</p></section></div>`}

let sandboxCaseId='ko', sandboxState=null;
const money2=v=>(v||0).toLocaleString(undefined,{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2});
const pct2=v=>(((v||0)*100).toFixed(2)+'%');
function sandboxCase(){return (typeof SANDBOX_CASES!=='undefined'?SANDBOX_CASES:[]).find(c=>c.id===sandboxCaseId) || (typeof SANDBOX_CASES!=='undefined'?SANDBOX_CASES[0]:null)}
function sandboxReset(id){if(id)sandboxCaseId=id;let c=sandboxCase();if(!c)return;sandboxState={sharePrice:c.sharePrice,costBasis:c.costBasis,strike:c.strike,premium:c.premium,days:c.days,endingPrice:c.sharePrice};render()}
function sandboxSet(k,v){if(!sandboxState)sandboxReset();sandboxState[k]=parseFloat(v)||0;render()}
function sandboxCalc(){let c=sandboxCase(),s=sandboxState;if(!c||!s)return{};let prem=s.premium,called=s.endingPrice>=s.strike,sale=called?s.strike:s.endingPrice,stockPL=sale-s.costBasis,totalPL=stockPL+prem,premiumIncome=prem*c.shares,premiumYield=prem/s.costBasis,monthlyEquivalent=premiumYield*30/Math.max(1,s.days),premiumRunRate=monthlyEquivalent*12,downsideCushion=prem/s.sharePrice,upsideToStrike=(s.strike-s.sharePrice)/s.sharePrice,breakeven=s.costBasis-prem,maxProfit=Math.max(0,s.strike-s.costBasis)+prem,maxLoss=s.costBasis-prem,totalReturn=totalPL/s.costBasis,near=1-Math.min(1,Math.abs(s.strike-s.sharePrice)/(s.sharePrice*.08)),moneyness=(s.sharePrice-s.strike)/s.sharePrice,pressure=Math.max(5,Math.min(95,Math.round(35+near*30+(moneyness>0?25:0)+(s.days>30?4:0))));return{called,sale,stockPL,totalPL,premiumIncome,premiumYield,monthlyEquivalent,premiumRunRate,downsideCushion,upsideToStrike,breakeven,maxProfit,maxLoss,totalReturn,pressure}}
function sandboxRow(k,label,min,max,step,help=''){let v=sandboxState[k];let dec=step<1?2:0;return`<div class="sandboxControl"><div><div class="controlLabel">${label}</div>${help?`<div class="controlHelp">${help}</div>`:''}<input type="range" min="${min}" max="${max}" step="${step}" value="${v}" oninput="sandboxSet('${k}',this.value)"></div><input class="sandboxNum" type="number" min="${min}" max="${max}" step="${step}" value="${Number(v).toFixed(dec)}" oninput="sandboxSet('${k}',this.value)"></div>`}
function sandboxChart(m){let c=sandboxCase(),s=sandboxState,xMin=Math.min(s.sharePrice,s.strike,s.costBasis)*.88,xMax=Math.max(s.sharePrice,s.strike,s.costBasis)*1.12,ys=[];for(let i=0;i<=28;i++){let x=xMin+(xMax-xMin)*i/28;ys.push((Math.min(x,s.strike)-s.costBasis)+s.premium);ys.push((x-s.costBasis)+s.premium)}let yMin=Math.min(-1,...ys)*1.18,yMax=Math.max(1,...ys)*1.18,W=760,H=330,L=60,R=20,T=24,B=46,X=x=>L+(x-xMin)/(xMax-xMin)*(W-L-R),Y=y=>T+(yMax-y)/(yMax-yMin)*(H-T-B);let grid='';for(let i=0;i<=6;i++){let y=yMin+(yMax-yMin)*i/6;grid+=`<line x1="${L}" y1="${Y(y)}" x2="${W-R}" y2="${Y(y)}" stroke="rgba(255,255,255,.10)"/><text x="8" y="${Y(y)+4}" fill="#dbeafe" font-size="12">${y.toFixed(1)}</text>`}for(let i=0;i<=6;i++){let x=xMin+(xMax-xMin)*i/6;grid+=`<line x1="${X(x)}" y1="${T}" x2="${X(x)}" y2="${H-B}" stroke="rgba(255,255,255,.07)"/><text x="${X(x)-14}" y="${H-18}" fill="#dbeafe" font-size="12">${x.toFixed(0)}</text>`}let pc=[],ps=[];for(let i=0;i<=80;i++){let x=xMin+(xMax-xMin)*i/80,yC=(Math.min(x,s.strike)-s.costBasis)+s.premium,yS=(x-s.costBasis)+s.premium;pc.push(`${X(x).toFixed(1)},${Y(yC).toFixed(1)}`);ps.push(`${X(x).toFixed(1)},${Y(yS).toFixed(1)}`)}let cx=X(s.sharePrice),ex=X(s.endingPrice);return`<svg viewBox="0 0 760 330" preserveAspectRatio="none">${grid}<line x1="${L}" y1="${Y(0)}" x2="${W-R}" y2="${Y(0)}" stroke="rgba(255,255,255,.28)"/><polyline points="${ps.join(' ')}" fill="none" stroke="#31d47a" stroke-width="3"/><polyline points="${pc.join(' ')}" fill="none" stroke="#ffd166" stroke-width="3" stroke-dasharray="10 8"/><line x1="${cx}" y1="${T}" x2="${cx}" y2="${H-B}" stroke="#fff" stroke-width="1" stroke-dasharray="4 4"/><line x1="${ex}" y1="${T}" x2="${ex}" y2="${H-B}" stroke="#7c9cff" stroke-width="2"/><circle cx="${ex}" cy="${Y(m.totalPL)}" r="5" fill="#7c9cff"/><text x="${L}" y="18" fill="#31d47a" font-size="13">Green: own stock + premium</text><text x="${L+220}" y="18" fill="#ffd166" font-size="13">Gold: covered call payoff</text></svg>`}
function quickScenario(label,val){return`<button onclick="sandboxSet('endingPrice',${val})">${label}<br><span class="small">${money2(val)}</span></button>`}
function sandboxPage(){let c=sandboxCase();if(!c)return`<section class="card"><div class="label">Sandbox</div><p>No sandbox cases loaded.</p></section>`;if(!sandboxState)sandboxReset(c.id);let s=sandboxState,m=sandboxCalc(),expText=c.expiration==='Completed'?'Completed trade case':`Expires ${c.expiration}`;let tabs=SANDBOX_CASES.map(x=>`<button class="${x.id===sandboxCaseId?'active':''}" onclick="sandboxReset('${x.id}')">${sandboxCaseLabel(x)}</button>`).join('');let controls=sandboxRow('sharePrice','Share Price',c.sharePrice*.75,c.sharePrice*1.25,.01,'Current stock price used for relationship modeling.')+sandboxRow('costBasis','Cost Basis',c.costBasis*.75,c.costBasis*1.25,.01)+sandboxRow('strike','Strike Price',c.sharePrice*.80,c.sharePrice*1.20,.5,'Educational slider. Real option chains use discrete strike increments.')+sandboxRow('premium','Premium Received',.01,Math.max(c.premium*3,c.sharePrice*.08),.01,'Editable because V1 is educational, not a live quote.')+sandboxRow('days','Days to Expiration',1,90,1)+sandboxRow('endingPrice','Ending Stock Price',c.sharePrice*.75,c.sharePrice*1.25,.01,'Scenario price at expiration.');let rows=[['Covered shares',c.shares],['Strike vs current',pct2((s.strike-s.sharePrice)/s.sharePrice)],['Downside cushion from premium',pct2(m.downsideCushion)],['Break-even at expiration',money2(m.breakeven)],['Max upside before assignment',money2(Math.max(0,s.strike-s.sharePrice)*c.shares)],['Dividend income in model','Excluded in v1'],['Modeled scenario outcome',m.called?'Called away':'Shares retained'],['Monthly premium equivalent',pct2(m.monthlyEquivalent)],['12-month premium run rate',pct2(m.premiumRunRate)]].map(r=>`<div class="sandboxSummaryRow"><span>${r[0]}</span><b>${r[1]}</b></div>`).join('');return`<div class="stack sandbox"><section class="note"><b>Educational Sandbox:</b> Start with a real trade from the experiment. Change strike, premium, DTE, and stock movement to see how the modeled outcome changes. This is not a live option quote, prediction, or recommendation.</section><section class="note warnNote"><b>Model notes:</b> Real broker option chains use specific strikes and expirations that vary by ticker and duration. Premium run rate is normalized to a 30-day monthly equivalent and multiplied by 12; it is not a guarantee. Dividends are tracked in the live dashboard but excluded from Sandbox v1.</section><section class="card"><div class="label">Case Studies</div><div class="sandboxTabs">${tabs}</div></section><div class="grid sandboxMetrics"><section class="card caseCard"><div class="label">Selected Case</div><div class="sandboxTitle">${c.ticker} — ${sandboxCaseName(c)}</div><p>${c.description}</p><p class="lesson">${c.lesson}</p><div class="pills"><span class="pill">${c.account}</span><span class="pill">${c.bucket}</span><span class="pill">${c.contract}</span></div></section>${metric('Premium Income',money2(m.premiumIncome),'good').replace('</section>',`<div class="small">Income from this ${Math.round(s.days)}-day contract</div></section>`)}${metric('Contract Premium Yield',pct2(m.premiumYield),'good').replace('</section>',`<div class="small">Premium ÷ cost basis for this DTE</div></section>`)}${metric('Contract Duration',Math.round(s.days)+' days','warn').replace('</section>',`<div class="small">${expText}</div></section>`)}${metric('Premium Run Rate',pct2(m.premiumRunRate),'warn').replace('</section>',`<div class="small">30-day equivalent × 12</div></section>`)}${metric('Real Trade Status',c.realStatus,'good').replace('</section>',`<div class="small">Scenario outcome shown below</div></section>`)}</div><div class="grid sandboxWork"><section class="card"><div class="label">Adjust Assumptions</div>${controls}<button class="resetBtn" onclick="sandboxReset()">Reset to Baseline Case Data</button><div class="note dividendNote"><b>Dividend note:</b> Sandbox v1 excludes dividends because ex-dividend dates and early assignment can change actual results.</div></section><section class="card"><div class="label">Payoff at Expiration</div><div class="chartWrap">${sandboxChart(m)}</div><div class="chartFooter"><div>Break-even <b>${money2(m.breakeven)}</b></div><div>Max profit <b>${money2(m.maxProfit)}</b></div><div>Max loss <b>${money2(m.maxLoss)}</b></div><div>Upside to strike <b>${pct2(m.upsideToStrike)}</b></div><div>Downside cushion <b>${pct2(m.downsideCushion)}</b></div></div></section><section class="card"><div class="label">Tradeoff Summary</div>${rows}<div class="pressure"><span>Assignment pressure</span><div class="pressBar"><span style="width:${m.pressure}%"></span></div><b>${m.pressure<35?'Low':m.pressure<65?'Moderate':'High'} (${m.pressure}/100)</b></div></section></div><div class="grid two"><section class="card"><div class="label">Quick Scenarios</div><div class="quickScenarios">${quickScenario('Stock down 5%',s.sharePrice*.95)}${quickScenario('Stock flat',s.sharePrice)}${quickScenario('Stock up 5%',s.sharePrice*1.05)}${quickScenario('At strike',s.strike)}${quickScenario('Above strike 5%',s.strike*1.05)}${quickScenario('Reset current',c.sharePrice)}</div></section><section class="card"><div class="label">What This Means</div><p>${m.called?`Modeled scenario: at the selected ending price, the option would finish above the strike. The model assumes shares are sold at <b>${money2(s.strike)}</b>, you keep the premium, and upside above the strike is capped.`:`Modeled scenario: at the selected ending price, the option would expire worthless. You keep the shares, the premium, and any future decision is reset for the next call.`}</p></section></div></div>`}

function safeText(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function addInvestment(){let t=prompt('Ticker to add');if(!t)return;let notes=prompt('Notes','')||'',kind=confirm('OK = Core Moat · Cancel = Tactical')?'core':'tactical';MDLMarket.addUniverse(t,notes,kind);render()}
function editInvestment(t){let x=MDLMarket.tags()[t]||{},notes=prompt('Notes for '+t,x.notes||'');if(notes!==null)MDLMarket.updateTag(t,{notes});render()}
function toggleInvestment(t,k){let x=MDLMarket.tags()[t]||{};MDLMarket.updateTag(t,{[k]:!x[k],active:true});render()}
function removeInvestment(t){if(confirm('Remove '+t+' from the active investment universe? Historical market data will be retained.')){MDLMarket.removeUniverse(t);render()}}
let universeView={sort:'ticker',direction:1,status:'all',maxCost:'',query:''};
function setUniverseSort(value){
  if(universeView.sort===value)universeView.direction*=-1;
  else{
    universeView.sort=value;
    universeView.direction=['ticker','name','price','cost'].includes(value)?1:-1;
  }
  render();
}
function setUniverseControl(key,value){universeView[key]=value;render()}
function evidenceRecord(ticker){return window.MDLEvidenceCensus?.records?.[ticker]||null}
function evidenceStatusLabel(status){return({Scored:'Scored',ScoreWithheld:'Score withheld',ProfileExcluded:'Profile excluded',AcquisitionFailure:'Acquisition failed',EvaluationFailure:'Evaluation failed'})[status]||'Not in census'}
function evidenceStatusClass(status){return({Scored:'scored',ScoreWithheld:'withheld',ProfileExcluded:'excluded',AcquisitionFailure:'failed',EvaluationFailure:'failed'})[status]||'missing'}
function evidenceCell(record){
  if(!record)return'<span class="evidence-state missing">Not in census</span>';
  let detail=record.coverage!=null?`${record.coverage.toFixed(1)}% coverage`:record.filingPeriodEnd?`Period ${safeText(record.filingPeriodEnd)}`:'';
  return`<span class="evidence-state ${evidenceStatusClass(record.status)}">${record.status==='Scored'?`<strong>${record.score.toFixed(1)}</strong>`:safeText(evidenceStatusLabel(record.status))}${detail?`<small>${detail}</small>`:''}</span>`;
}
function evidenceLaunchUrl(row){
  const params=new URLSearchParams({ticker:row.ticker,company:row.name||row.ticker,source:'TMDL',marketUrl:'https://themathdoesntlie.com/covered-call-lab/market-data.json'});
  if(Number(row.price)>0)params.set('price',String(row.price));
  const observed=row.lastQuoteRefresh||row.lastRefresh;
  if(observed){const date=new Date(observed);if(!Number.isNaN(date.valueOf()))params.set('marketDate',date.toISOString().slice(0,10))}
  return`https://tmdl-evidence-engine.sean-t-curley.workers.dev/?${params.toString()}`;
}
function universePageV28(){
  const census=window.MDLEvidenceCensus||{population:0,scored:0,records:{}};
  let rows=MDLMarket.investmentRows().map(row=>{
    const evidence=evidenceRecord(row.ticker);
    return{...row,evidence,cost100:Number(row.price)>0?Number(row.price)*100:null};
  });
  const q=String(universeView.query||'').trim().toUpperCase();
  rows=rows.filter(row=>{
    if(q&&!`${row.ticker} ${row.name||''} ${row.sector||''}`.toUpperCase().includes(q))return false;
    if(universeView.status!=='all'){
      const status=row.evidence?.status||'NotInCensus';
      if(universeView.status==='failed'){
        if(!['AcquisitionFailure','EvaluationFailure'].includes(status))return false;
      }else if(status!==universeView.status)return false;
    }
    if(universeView.maxCost&&(!(row.cost100>0)||row.cost100>Number(universeView.maxCost)))return false;
    return true;
  });
  const value=(row,key)=>({ticker:row.ticker,name:row.name||row.ticker,price:Number(row.price)||null,cost:row.cost100,yield:row.dividendYield==null?null:Number(row.dividendYield),score:row.evidence?.score??null,coverage:row.evidence?.coverage??null})[key];
  rows.sort((a,b)=>{
    const av=value(a,universeView.sort),bv=value(b,universeView.sort);
    if(av==null&&bv==null)return a.ticker.localeCompare(b.ticker);
    if(av==null)return 1;if(bv==null)return-1;
    return universeView.direction*(typeof av==='string'?av.localeCompare(bv):av-bv);
  });
  const scored=rows.filter(row=>row.evidence?.status==='Scored').length;
  const arrow=universeView.direction===1?'↑':'↓';
  return`${banner()}<div class="stack"><section class="hero"><div class="label">Editable Investment Universe · Covered Call Lab v2.9.2</div><div style="font-size:20px;font-weight:800;margin-top:8px">Market affordability meets governed evidence.</div><p class="small">Current Finnhub prices and dividend yields support candidate screening. Evidence scores and publication status come from the frozen S&amp;P 500 census dated ${safeText(census.marketDate||'2026-08-11')}.</p><div class="pills"><span class="pill">${census.scored||153}/${census.population||503} S&amp;P companies scored</span><span class="pill">${rows.length} rows shown</span><span class="pill">${scored} scored in view</span><span class="pill">Evidence Integration ${safeText(census.integrationVersion||'6.5.2')}</span></div><button class="actionBtn" onclick="addInvestment()">+ Add Ticker</button></section><section class="card universe-research-card"><div class="universe-controls"><label>Find<input type="search" value="${safeText(universeView.query)}" placeholder="Ticker, company, or sector" onchange="setUniverseControl('query',this.value)"></label><label>Evidence status<select onchange="setUniverseControl('status',this.value)"><option value="all" ${universeView.status==='all'?'selected':''}>All outcomes</option><option value="Scored" ${universeView.status==='Scored'?'selected':''}>Scored</option><option value="ScoreWithheld" ${universeView.status==='ScoreWithheld'?'selected':''}>Score withheld</option><option value="ProfileExcluded" ${universeView.status==='ProfileExcluded'?'selected':''}>Profile excluded</option><option value="failed" ${universeView.status==='failed'?'selected':''}>Failures</option><option value="NotInCensus" ${universeView.status==='NotInCensus'?'selected':''}>Not in census</option></select></label><label>Affordable 100 shares<select onchange="setUniverseControl('maxCost',this.value)"><option value="" ${universeView.maxCost===''?'selected':''}>Any cost</option>${[2500,5000,10000,15000,25000].map(amount=>`<option value="${amount}" ${String(universeView.maxCost)===String(amount)?'selected':''}>${fmt(amount)} or less</option>`).join('')}</select></label><label>Sort by<select onchange="setUniverseSort(this.value)"><option value="ticker" ${universeView.sort==='ticker'?'selected':''}>Ticker</option><option value="name" ${universeView.sort==='name'?'selected':''}>Company</option><option value="price" ${universeView.sort==='price'?'selected':''}>Share price</option><option value="cost" ${universeView.sort==='cost'?'selected':''}>100-share cost</option><option value="yield" ${universeView.sort==='yield'?'selected':''}>Dividend yield</option><option value="score" ${universeView.sort==='score'?'selected':''}>Evidence score</option><option value="coverage" ${universeView.sort==='coverage'?'selected':''}>Evidence coverage</option></select></label><button class="sort-direction" onclick="universeView.direction*=-1;render()" title="Reverse sort direction">${arrow}</button><button class="secondaryAction" onclick="universeView={sort:'ticker',direction:1,status:'all',maxCost:'',query:''};render()">Reset</button></div><div class="universe-table-wrap"><table class="universe-research-table"><thead><tr><th>Ticker</th><th>Company</th><th class="num"><button onclick="setUniverseSort('price')">Price</button></th><th class="num"><button onclick="setUniverseSort('cost')">100 shares</button></th><th class="num"><button onclick="setUniverseSort('yield')">Dividend yield</button></th><th><button onclick="setUniverseSort('score')">Evidence</button></th><th>Tags</th><th>Manage</th></tr></thead><tbody>${rows.map(row=>`<tr><td class="ticker">${safeText(row.ticker)}</td><td><strong>${safeText(row.name||row.ticker)}</strong><small class="cell-subtext">${safeText(row.sector||'—')}${row.notes?` · ${safeText(row.notes)}`:''}</small></td><td class="num">${row.price?fmt2(row.price):'—'}</td><td class="num">${row.cost100?fmt(row.cost100):'—'}</td><td class="num">${row.dividendYield!=null?pct(row.dividendYield):'—'}</td><td>${evidenceCell(row.evidence)}</td><td><div class="pills">${row.coreMoat?'<span class="pill">Core Moat</span>':''}${row.tactical?'<span class="pill">Tactical</span>':''}${row.inSCHD?'<span class="pill">In SCHD</span>':''}${row.currentlyOwned?'<span class="pill">Owned</span>':''}${row.coveredCall?'<span class="pill">Covered Call</span>':''}</div></td><td><div class="rowActions"><a class="evidence-link" href="${evidenceLaunchUrl(row)}" target="_blank" rel="noopener noreferrer">Evidence</a><button onclick="toggleInvestment('${row.ticker}','coreMoat')">Core</button><button onclick="toggleInvestment('${row.ticker}','tactical')">Tactical</button><button onclick="editInvestment('${row.ticker}')">Notes</button><button class="dangerBtn" onclick="removeInvestment('${row.ticker}')">Remove</button></div></td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="empty-filter">No investment-universe rows match these filters.</div>'}</section><section class="note"><b>Research boundary:</b> Evidence scores are frozen observations from 2026-08-11. Current prices, yields, and 100-share costs can change. A withheld, excluded, failed, or unsupported result is not a zero.</section></div>`;
}

function schdPageV271(){let rows=MDLMarket.schdRows();return`${banner()}<div class="stack"><section class="hero"><div class="label">SCHD Universe</div><div style="font-size:20px;font-weight:800;margin-top:8px">A list membership, never a second stock database.</div><p class="small">Membership is seeded from Schwab Asset Management's SCHD holdings dated 2026-08-06. Finnhub supplies market fields from the same master security records used by the S&amp;P, Moat, and portfolio views.</p></section><section class="card"><div class="label">${rows.length} equity holdings · Schwab membership 2026-08-06</div><table><thead><tr><th>Ticker</th><th>Company</th><th>Sector</th><th class="num">Price</th><th class="num">Market Cap</th><th class="num">Dividend Yield</th><th>Roles</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="ticker">${safeText(r.ticker)}</td><td>${safeText(r.name||r.ticker)}</td><td>${safeText(r.sector||'—')}</td><td class="num">${r.price?fmt2(r.price):'—'}</td><td class="num">${r.marketCap?fmt(r.marketCap):'—'}</td><td class="num">${r.dividendYield!=null?pct(r.dividendYield):'—'}</td><td>${r.currentlyOwned?'<span class="pill">Owned</span>':''}${r.coreMoat?'<span class="pill">Moat</span>':''}</td></tr>`).join('')}</tbody></table></section><section class="note">SCHD's published total also includes cash, a money-market position, and futures. This universe intentionally tracks the 99 stock holdings only. SCHD names outside the S&amp;P 500 remain first-class master securities rather than duplicate records.</section></div>`}
function marketDbPageV271(){let s=MDLMarket.status(),rows=MDLMarket.sp500Rows(),pricePct=s.backgroundTotal?Math.round(s.backgroundDone/s.backgroundTotal*100):0,fundPct=s.fundamentalTotal?Math.round(s.fundamentalDone/s.fundamentalTotal*100):100,lists=Object.values(MDLMarket.listCatalog()),lastSweep=s.lastPriceSweepCompletedAt?new Date(s.lastPriceSweepCompletedAt).toLocaleString():'Not yet completed';return`${banner()}<div class="stack"><section class="hero"><div class="label">Internal System of Record</div><div style="font-size:22px;font-weight:900;margin-top:8px">Master Securities Database</div><p>${rows.length} S&amp;P 500 securities. The database maintains itself in the background and remembers completed work across browser sessions.</p><div class="pills">${lists.map(x=>`<span class="pill">${safeText(x.name)}</span>`).join('')}<span class="pill">Finnhub: ${MDLMarket.hasToken()?'Connected':'Unavailable'}</span><span class="pill">Free-tier guardrail: 50 calls/min</span></div><p class="small">There is intentionally no S&amp;P refresh button. A price sweep runs automatically when the prior completed sweep is at least 24 hours old. If the page closes at 327/503, the next session resumes the same sweep at 328. Monthly fundamental maintenance is also resumable. Refresh Portfolio never restarts either background job.</p></section><section class="card"><div class="label">Automatic S&amp;P Price Maintenance</div><div class="progressBar"><span style="width:${pricePct}%"></span></div><div class="marketStatus"><b>${safeText(s.backgroundStatus)}</b><span>${s.backgroundDone}/${s.backgroundTotal} ${safeText(s.backgroundActiveTicker||'')}</span><span>Last completed sweep: ${safeText(lastSweep)}</span><span>${s.backgroundFailed?`${s.backgroundFailed} failed · ${safeText(s.lastError)}`:''}</span></div></section><section class="card"><div class="label">Monthly Fundamental Maintenance</div><div class="progressBar"><span style="width:${fundPct}%"></span></div><div class="marketStatus"><b>${safeText(s.fundamentalStatus)}</b><span>${s.fundamentalDone}/${s.fundamentalTotal||0}</span><span>Market cap, shares outstanding, and dividend yield persist between monthly refreshes and are recomputed from current price where possible.</span></div></section><section class="card"><div class="label">Master Securities · S&amp;P 500 View (${rows.length})</div><table><thead><tr><th>Ticker</th><th>Company</th><th>Sector / Industry</th><th class="num">Current Price</th><th class="num">Market Cap</th><th class="num">Shares Outstanding</th><th class="num">Dividend Yield</th><th>Last Quote</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="ticker">${safeText(r.ticker)}</td><td>${safeText(r.name)}</td><td>${safeText(r.sector||'—')}</td><td class="num">${r.price?fmt2(r.price):'—'}</td><td class="num">${r.marketCap?fmt(r.marketCap):'—'}</td><td class="num">${r.sharesOutstanding?Number(r.sharesOutstanding).toLocaleString(undefined,{maximumFractionDigits:0}):'—'}</td><td class="num">${r.dividendYield!=null?pct(r.dividendYield):'—'}</td><td>${r.lastQuoteRefresh?new Date(r.lastQuoteRefresh).toLocaleString():'Awaiting background quote'}</td></tr>`).join('')}</tbody></table></section></div>`}
function marketDbPageV273(){let s=MDLMarket.status();return marketDbPageV271()
  .replace(`${MDLMarket.sp500Rows().length} S&amp;P 500 securities. The database maintains itself in the background and remembers completed work across browser sessions.`,`${MDLMarket.sp500Rows().length} S&amp;P 500 securities plus tagged SCHD equities share one deduplicated master snapshot. The ${s.backgroundTotal}-security refresh runs once centrally for every visitor.`)
  .replace('There is intentionally no S&amp;P refresh button. A price sweep runs automatically when the prior completed sweep is at least 24 hours old. If the page closes at 327/503, the next session resumes the same sweep at 328. Monthly fundamental maintenance is also resumable. Refresh Portfolio never restarts either background job.','Current holdings always receive priority. One browser tab owns the broader S&amp;P/SCHD sweep at no more than 20 calls per minute. A Finnhub throttle pauses without advancing the cursor, then retries the same ticker after cooldown. Successful prices and timestamps persist; individual failures retain the prior valid value.')
  .replace('Free-tier guardrail: 50 calls/min','Guardrail: 20 calls/min + throttle cooldown')
  .replace('Automatic S&amp;P Price Maintenance','Resumable Browser Price Maintenance')
  .replace('Market cap, shares outstanding, and dividend yield persist between monthly refreshes and are recomputed from current price where possible.','The scheduled GitHub snapshot seeds fundamentals. Current prices refresh through the private Cloudflare Finnhub gateway and persist in the browser database.')
  .replaceAll('Awaiting background quote','Awaiting GitHub market refresh')}

let marketDbView={sort:'ticker',direction:1,status:'all',maxCost:'',minYield:'',minScore:'',sector:'all',query:''};
function marketDbSetSort(value){
  if(marketDbView.sort===value)marketDbView.direction*=-1;
  else{marketDbView.sort=value;marketDbView.direction=['ticker','name','sector','price','cost'].includes(value)?1:-1}
  render();
}
function marketDbSetControl(key,value){marketDbView[key]=value;render()}
function marketDbReset(){marketDbView={sort:'ticker',direction:1,status:'all',maxCost:'',minYield:'',minScore:'',sector:'all',query:''};render()}
function marketDbPageV290(){
  const census=window.MDLEvidenceCensus||{population:0,scored:0,records:{}};
  const s=MDLMarket.status(),allRows=MDLMarket.sp500Rows(),tags=MDLMarket.tags();
  const pricePct=s.backgroundTotal?Math.round(s.backgroundDone/s.backgroundTotal*100):0;
  const fundPct=s.fundamentalTotal?Math.round(s.fundamentalDone/s.fundamentalTotal*100):100;
  const lists=Object.values(MDLMarket.listCatalog());
  const lastSweep=s.lastPriceSweepCompletedAt?new Date(s.lastPriceSweepCompletedAt).toLocaleString():'Not yet completed';
  const sectors=[...new Set(allRows.map(r=>r.sector).filter(Boolean))].sort();
  let rows=allRows.map(row=>{
    const evidence=evidenceRecord(row.ticker),tag=tags[row.ticker]||{};
    return{...row,...tag,evidence,cost100:Number(row.price)>0?Number(row.price)*100:null};
  });
  const q=String(marketDbView.query||'').trim().toUpperCase();
  rows=rows.filter(row=>{
    if(q&&!`${row.ticker} ${row.name||''} ${row.sector||''}`.toUpperCase().includes(q))return false;
    if(marketDbView.sector!=='all'&&row.sector!==marketDbView.sector)return false;
    if(marketDbView.status!=='all'){
      const status=row.evidence?.status||'NotInCensus';
      if(marketDbView.status==='failed'){
        if(!['AcquisitionFailure','EvaluationFailure'].includes(status))return false;
      }else if(status!==marketDbView.status)return false;
    }
    if(marketDbView.maxCost&&(!(row.cost100>0)||row.cost100>Number(marketDbView.maxCost)))return false;
    if(marketDbView.minYield!==''&&(row.dividendYield==null||Number(row.dividendYield)<Number(marketDbView.minYield)))return false;
    if(marketDbView.minScore!==''&&(row.evidence?.status!=='Scored'||Number(row.evidence.score)<Number(marketDbView.minScore)))return false;
    return true;
  });
  const value=(row,key)=>({ticker:row.ticker,name:row.name||row.ticker,sector:row.sector||'',price:Number(row.price)||null,cost:row.cost100,yield:row.dividendYield==null?null:Number(row.dividendYield),score:row.evidence?.score??null,coverage:row.evidence?.coverage??null})[key];
  rows.sort((a,b)=>{
    const av=value(a,marketDbView.sort),bv=value(b,marketDbView.sort);
    if(av==null&&bv==null)return a.ticker.localeCompare(b.ticker);
    if(av==null)return 1;if(bv==null)return-1;
    return marketDbView.direction*(typeof av==='string'?av.localeCompare(bv):av-bv);
  });
  const scored=rows.filter(row=>row.evidence?.status==='Scored').length;
  const outcomes=Object.values(census.records||{}).reduce((acc,r)=>(acc[r.status]=(acc[r.status]||0)+1,acc),{});
  const arrow=marketDbView.direction===1?'↑':'↓';
  return`${banner()}<div class="stack"><section class="hero"><div class="label">Internal System of Record · Covered Call Lab v2.9.2</div><div style="font-size:22px;font-weight:900;margin-top:8px">S&amp;P 500 Evidence Research Database</div><p>One deduplicated master market database now joins affordability, income, governed evidence outcomes, and TMDL portfolio roles across the full S&amp;P 500—not only the curated Investment Universe.</p><div class="pills"><span class="pill">${allRows.length} S&amp;P companies</span><span class="pill">${census.scored||153} scored</span><span class="pill">${outcomes.ScoreWithheld||210} withheld</span><span class="pill">${outcomes.ProfileExcluded||136} excluded</span><span class="pill">${(outcomes.AcquisitionFailure||0)+(outcomes.EvaluationFailure||0)} failures</span><span class="pill">${rows.length} rows shown</span><span class="pill">${scored} scored in view</span></div><p class="small">Evidence Integration ${safeText(census.integrationVersion||'6.5.2')} · frozen ${safeText(census.marketDate||'2026-08-11')}. Current price and dividend fields continue to refresh through the shared market system.</p></section><section class="card"><div class="label">Resumable Browser Price Maintenance</div><div class="progressBar"><span style="width:${pricePct}%"></span></div><div class="marketStatus"><b>${safeText(s.backgroundStatus)}</b><span>${s.backgroundDone}/${s.backgroundTotal} ${safeText(s.backgroundActiveTicker||'')}</span><span>Last completed sweep: ${safeText(lastSweep)}</span><span>${s.backgroundFailed?`${s.backgroundFailed} failed · ${safeText(s.lastError)}`:''}</span></div></section><section class="card"><div class="label">Monthly Fundamental Maintenance</div><div class="progressBar"><span style="width:${fundPct}%"></span></div><div class="marketStatus"><b>${safeText(s.fundamentalStatus)}</b><span>${s.fundamentalDone}/${s.fundamentalTotal||0}</span><span>The scheduled GitHub snapshot seeds fundamentals. Current prices refresh through the private Cloudflare Finnhub gateway and persist in the browser database.</span></div></section><section class="card universe-research-card market-research-card"><div class="universe-controls market-research-controls"><label>Find<input type="search" value="${safeText(marketDbView.query)}" placeholder="Ticker, company, or sector" onchange="marketDbSetControl('query',this.value)"></label><label>Sector<select onchange="marketDbSetControl('sector',this.value)"><option value="all">All sectors</option>${sectors.map(sector=>`<option value="${safeText(sector)}" ${marketDbView.sector===sector?'selected':''}>${safeText(sector)}</option>`).join('')}</select></label><label>Evidence status<select onchange="marketDbSetControl('status',this.value)"><option value="all" ${marketDbView.status==='all'?'selected':''}>All outcomes</option><option value="Scored" ${marketDbView.status==='Scored'?'selected':''}>Scored</option><option value="ScoreWithheld" ${marketDbView.status==='ScoreWithheld'?'selected':''}>Score withheld</option><option value="ProfileExcluded" ${marketDbView.status==='ProfileExcluded'?'selected':''}>Profile excluded</option><option value="failed" ${marketDbView.status==='failed'?'selected':''}>Failures</option></select></label><label>Affordable 100 shares<select onchange="marketDbSetControl('maxCost',this.value)"><option value="">Any cost</option>${[2500,5000,10000,15000,25000].map(amount=>`<option value="${amount}" ${String(marketDbView.maxCost)===String(amount)?'selected':''}>${fmt(amount)} or less</option>`).join('')}</select></label><label>Minimum yield<select onchange="marketDbSetControl('minYield',this.value)"><option value="">Any yield</option>${[1,2,3,4,5,6].map(value=>`<option value="${value}" ${String(marketDbView.minYield)===String(value)?'selected':''}>${value}% or higher</option>`).join('')}</select></label><label>Minimum score<select onchange="marketDbSetControl('minScore',this.value)"><option value="">Any score</option>${[50,60,65,70,75,80].map(value=>`<option value="${value}" ${String(marketDbView.minScore)===String(value)?'selected':''}>${value} or higher</option>`).join('')}</select></label><label>Sort by<select onchange="marketDbSetSort(this.value)"><option value="ticker" ${marketDbView.sort==='ticker'?'selected':''}>Ticker</option><option value="name" ${marketDbView.sort==='name'?'selected':''}>Company</option><option value="sector" ${marketDbView.sort==='sector'?'selected':''}>Sector</option><option value="price" ${marketDbView.sort==='price'?'selected':''}>Share price</option><option value="cost" ${marketDbView.sort==='cost'?'selected':''}>100-share cost</option><option value="yield" ${marketDbView.sort==='yield'?'selected':''}>Dividend yield</option><option value="score" ${marketDbView.sort==='score'?'selected':''}>Evidence score</option><option value="coverage" ${marketDbView.sort==='coverage'?'selected':''}>Evidence coverage</option></select></label><button class="sort-direction" onclick="marketDbView.direction*=-1;render()" title="Reverse sort direction">${arrow}</button><button class="secondaryAction" onclick="marketDbReset()">Reset</button></div><div class="universe-table-wrap"><table class="universe-research-table market-research-table"><thead><tr><th>Ticker</th><th>Company</th><th class="num"><button onclick="marketDbSetSort('price')">Price</button></th><th class="num"><button onclick="marketDbSetSort('cost')">100 shares</button></th><th class="num"><button onclick="marketDbSetSort('yield')">Dividend yield</button></th><th><button onclick="marketDbSetSort('score')">Evidence</button></th><th>TMDL roles</th><th>Research</th></tr></thead><tbody>${rows.map(row=>`<tr><td class="ticker">${safeText(row.ticker)}</td><td><strong>${safeText(row.name||row.ticker)}</strong><small class="cell-subtext">${safeText(row.sector||'—')}${row.marketCap?` · Market cap ${fmt(row.marketCap)}`:''}${row.lastQuoteRefresh?` · Quote ${new Date(row.lastQuoteRefresh).toLocaleDateString()}`:''}</small></td><td class="num">${row.price?fmt2(row.price):'—'}</td><td class="num">${row.cost100?fmt(row.cost100):'—'}</td><td class="num">${row.dividendYield!=null?pct(row.dividendYield):'—'}</td><td>${evidenceCell(row.evidence)}</td><td><div class="pills">${row.coreMoat?'<span class="pill">Core Moat</span>':''}${row.tactical?'<span class="pill">Tactical</span>':''}${row.inSCHD?'<span class="pill">SCHD</span>':''}${row.currentlyOwned?'<span class="pill">Owned</span>':''}${row.coveredCall?'<span class="pill">Covered Call</span>':''}</div></td><td><div class="rowActions"><a class="evidence-link" href="${evidenceLaunchUrl(row)}" target="_blank" rel="noopener noreferrer">Evidence</a><button onclick="toggleInvestment('${row.ticker}','coreMoat')">${row.coreMoat?'Remove Core':'Add Core'}</button><button onclick="toggleInvestment('${row.ticker}','tactical')">${row.tactical?'Remove Tactical':'Add Tactical'}</button></div></td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="empty-filter">No S&amp;P 500 companies match these filters.</div>'}</section><section class="note"><b>Research boundary:</b> A withheld, excluded, failed, or unsupported result is a governed outcome—not a score of zero. Use the filters to form hypotheses; evaluate the scoring metrics only after comparing frozen evidence observations with Moat membership and Covered Call Lab outcomes.</section></div>`;
}
function enhanceRenderedPage(){
  if(page==='dashboard'&&DATA.releaseCommentary){let v=document.getElementById('view'),card=document.createElement('section');card.className='note commentary';card.innerHTML='<b>2.7.3 Monthly Commentary:</b> '+safeText(DATA.releaseCommentary);v.querySelector('.stack')?.appendChild(card)}
  if(page==='holdings'&&!DATA.optionMtmAvailable){let v=document.getElementById('view'),n=document.createElement('section');n.className='note warnNote';n.innerHTML='<b>Fidelity activity-file limitation:</b> the supplied ledger contains trades, premiums, dividends and cash activity but not current option marks. Stock values and strategy return are updated; open-call P/L and option liability remain unmarked rather than inventing prices. Portfolio Value therefore currently shows stock + cash.';v.querySelector('.stack')?.prepend(n)}
  if(page==='methodology'){let v=document.getElementById('view'),n=document.createElement('section');n.className='card';n.innerHTML='<div class="label">2.7.6 Market Data Architecture</div><p><b>Portfolio value:</b> ledger cash plus current ledger shares multiplied by the latest Finnhub stock price. Option market value, premiums, dividends, basis, and realized gains are excluded from that displayed total.</p><p><b>Two tiers:</b> <b>Refresh Portfolio</b> requests only the current ledger holdings and redraws immediately. A separate resumable sweep maintains the broader S&amp;P 500/SCHD universe without blocking that operation.</p><p><b>Rate-limit safety:</b> one browser tab owns background maintenance at 20 calls per minute. A Finnhub throttle creates a shared cooldown, keeps the cursor on the failed ticker, and retries it without discarding the prior valid price.</p><p><b>Persistence and fallback:</b> successful browser quotes and timestamps persist locally. The scheduled GitHub snapshot seeds the database; a failed request retains the last valid quote and is reported instead of being presented as current.</p><p><b>Identity model:</b> one ticker record can carry many roles — S&amp;P 500 constituent, Core Moat, Tactical, SCHD holding, currently owned, and/or covered-call position. Roles do not duplicate company or price data.</p>';v.querySelector('.stack')?.appendChild(n)}
}
const holdingsPageBeforeV275=holdingsPage;
holdingsPage=function(){let html=holdingsPageBeforeV275(),c=combined(),stockValue=holdingRows().reduce((s,h)=>s+h.value,0),formula=`<section class="note"><b>Portfolio Value formula:</b> ${fmt(stockValue)} current stock holdings + ${fmt(c.cash)} ledger cash = ${fmt(c.total)}. Open-option market value, premiums, dividends, cost basis, and realized gains are intentionally excluded from Portfolio Value.</section>`;return html.replace(/<section class="note"><b>Portfolio Value vs Stock Holdings Value:<\/b>[\s\S]*?<\/section>/,formula)};
function render(){nav();modeUI();let p=pages.find(x=>x[0]===page);document.getElementById('title').textContent=p[1];document.getElementById('sub').textContent=p[2];let views={dashboard:dashboard,holdings:holdingsPage,calls:callsPageV271,universe:universePageV28,schd:schdPageV271,benchmarks:benchmarksPage,methodology:methodology,sandbox:sandboxPage,marketdb:marketDbPageV290};document.getElementById('view').innerHTML=views[page]();enhanceRenderedPage()}
let marketRenderTimer=null;window.addEventListener('mdl-market-state',e=>{let s=e.detail||{},snapshotLoaded=market.has(page)&&Boolean(s.snapshotGeneratedAt),shouldRender=page==='marketdb'||s.portfolioRefreshing||snapshotLoaded||String(s.portfolioStatus||'').includes('complete');if(!shouldRender||marketRenderTimer)return;marketRenderTimer=setTimeout(()=>{marketRenderTimer=null;render()},250)});
render();
// V2.7.4: install the redraw listener first, then explicitly load a no-cache shared snapshot.
// This avoids relying on a window load event that may already have fired.
if(window.MDLMarket){
  MDLMarket.loadSnapshot(true).catch(e=>{
    quoteStatus='Shared market snapshot unavailable: '+e.message;
    render();
  });
}
